import{_ as a,c as r,o,ag as e}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"播放器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/player.md","filePath":"zh-CN/guide/player.md","lastUpdated":1791311600000}'),d={name:"zh-CN/guide/player.md"};function l(n,t,i,s,h,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="播放器" tabindex="-1">播放器 <a class="header-anchor" href="#播放器" aria-label="Permalink to &quot;播放器&quot;">​</a></h1><p>nPlyr 的播放器是一套由 <code>AVPlayer</code> 驱动、macOS 与 iOS 共用的内核。本页介绍日常控件与平台专属手势。</p><h2 id="打开内容" tabindex="-1">打开内容 <a class="header-anchor" href="#打开内容" aria-label="Permalink to &quot;打开内容&quot;">​</a></h2><p>从主屏幕你可以：</p><ul><li><strong>打开文件</strong>——将本地视频拖入窗口，或使用文件选择器。</li><li><strong>打开 URL</strong>——将直链（<code>.mp4</code>、<code>.m3u8</code>、<code>.flv</code>、<code>.ts</code> 等）粘贴到 URL 输入框。</li><li><strong>从嗅探器打开</strong>——将抓取的链接从<a href="/zh-CN/guide/browser.html">浏览器</a>抽屉直接发送给播放器。</li><li><strong>从小程序打开</strong>——点击可播放的条目，nPlyr 会通过<a href="/zh-CN/guide/miniapps.html">规则引擎</a>解析它。</li></ul><h2 id="常用控件-双平台通用" tabindex="-1">常用控件（双平台通用） <a class="header-anchor" href="#常用控件-双平台通用" aria-label="Permalink to &quot;常用控件（双平台通用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>作用</th></tr></thead><tbody><tr><td>播放 / 暂停</td><td>空格键（macOS）或轻点视频中心（iOS）</td></tr><tr><td>进度</td><td>拖动进度条，或使用下方平台手势</td></tr><tr><td>音量</td><td>系统 / 屏幕音量</td></tr><tr><td>倍速</td><td>通过倍速按钮在 0.5×–3× 之间调整</td></tr><tr><td>音轨</td><td>当源包含多音轨时可选择</td></tr><tr><td>字幕</td><td>加载外部 <code>.srt</code> / <code>.vtt</code>，或使用内嵌音轨</td></tr><tr><td>画中画</td><td>将视频弹出为悬浮的画中画窗口</td></tr><tr><td>AirPlay</td><td>将视频发送到 Apple TV 或 AirPlay 扬声器</td></tr><tr><td>DLNA（macOS）</td><td>投放到局域网中的 DLNA 设备</td></tr></tbody></table><h2 id="macos-手势与快捷键" tabindex="-1">macOS 手势与快捷键 <a class="header-anchor" href="#macos-手势与快捷键" aria-label="Permalink to &quot;macOS 手势与快捷键&quot;">​</a></h2><h3 id="触控板" tabindex="-1">触控板 <a class="header-anchor" href="#触控板" aria-label="Permalink to &quot;触控板&quot;">​</a></h3><ul><li><strong>横向滑动</strong>拖动时间线。拖动时<strong>预览</strong>新位置；当你抬起手指（或停顿 250 毫秒）时才真正跳转，因此误滑绝不会让视频乱跳。</li><li><strong>纵向滑动</strong>根据起始位置调整<strong>亮度</strong>或<strong>音量</strong>：视频<strong>左半侧</strong>控制亮度，<strong>右半侧</strong>控制音量。第一次滑动会锁定轴向，二者互不干扰。</li><li><strong>滚轮</strong>悬停在进度条上时可微调位置（每格 ±5%）。</li></ul><h3 id="亮度" tabindex="-1">亮度 <a class="header-anchor" href="#亮度" aria-label="Permalink to &quot;亮度&quot;">​</a></h3><p>macOS 不提供公开 API 来调暗其他应用的视频，因此 nPlyr 在视频与控件之间叠加一层调暗层。这只是视觉上的处理——底层画面本身并未改变。</p><h3 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h3><p>快捷键仅按<strong>修饰键</strong>（<code>⌘</code>、<code>⌥</code>、<code>⌃</code>、<code>⇧</code>）匹配——方向键与小键盘不参与匹配，因此方向键绑定始终可靠。在文本框（URL 栏、搜索框等）中输入时，单键快捷键会被抑制。</p><p>如果某个快捷键突然失效，请参阅<a href="/zh-CN/guide/troubleshooting.html">故障排查</a>。</p><h2 id="ios-手势" tabindex="-1">iOS 手势 <a class="header-anchor" href="#ios-手势" aria-label="Permalink to &quot;iOS 手势&quot;">​</a></h2><ul><li><strong>双击</strong>将屏幕分为三个区域：轻点<strong>左三分之一</strong>后退 10 秒，<strong>右三分之一</strong>前进 10 秒，<strong>中间</strong>播放 / 暂停（并在点击处显示涟漪）。</li><li>**长按（0.5 秒）**临时以 <strong>2.0×</strong> 播放；松开后恢复普通速度。</li><li>边缘<strong>死区</strong>（约 30 pt，或短边的 10%）被忽略，因此从屏幕边缘开始滑动不会误触手势。该死区仅在全屏时生效。</li></ul><h2 id="高级播放" tabindex="-1">高级播放 <a class="header-anchor" href="#高级播放" aria-label="Permalink to &quot;高级播放&quot;">​</a></h2><h3 id="多线路视频-json" tabindex="-1">多线路视频 JSON <a class="header-anchor" href="#多线路视频-json" aria-label="Permalink to &quot;多线路视频 JSON&quot;">​</a></h3><p>某些规则会返回一个结构化 JSON，描述多条视频线路（不同分辨率或 CDN）、字幕、歌词与音频 URL。nPlyr 将其解析为一个<strong>线路切换器</strong>，让你在不丢失进度的情况下切换线路。</p><h3 id="续播与换源" tabindex="-1">续播与换源 <a class="header-anchor" href="#续播与换源" aria-label="Permalink to &quot;续播与换源&quot;">​</a></h3><ul><li>nPlyr 会记住你停在哪里，并在下次提供<strong>续播</strong>选项。</li><li>在播放中途切换源时，交换瞬间会<strong>冻结最后一帧</strong>，以免屏幕闪黑。</li><li>在条目就绪之前发出的跳转会被<strong>排队</strong>，并在播放可以开始的瞬间立即应用——因此你永远不会在不知情的情况下从头重播。</li></ul><h3 id="边下边播" tabindex="-1">边下边播 <a class="header-anchor" href="#边下边播" aria-label="Permalink to &quot;边下边播&quot;">​</a></h3><p>你可以在文件仍在下载时就开始观看。参见<a href="/zh-CN/guide/downloads.html">下载与媒体库</a>。</p>',24)])])}const m=a(d,[["render",l]]);export{u as __pageData,m as default};
